// ════════════════════════════════════════════════════════════════════
// 💪 SYSTÈME MUSCLES SECONDAIRES + RÉCUPÉRATION (fondation rétrocompatible)
// ════════════════════════════════════════════════════════════════════
// Un exercice peut déclarer des muscles secondaires pondérés :
//   secondaryMuscles: [{ muscle: "Triceps", ratio: 0.5 }, { muscle: "Épaules", ratio: 0.3 }]
// Le muscle principal (champ `muscle`) compte toujours pour 1.0.
// Tant qu'un exercice n'a pas de secondaryMuscles, le comportement est INCHANGÉ.

// ⏱️ Temps de récupération individuel par muscle (en heures).
// Gros muscles = récup longue ; petits muscles = récup rapide.
const MUSCLE_RECOVERY_HOURS = {
    "Quadriceps":      72,
    "Ischio-jambiers": 72,
    "Fessiers":        72,
    "Dos":             72,
    "Pectoraux":       48,
    "Épaules":         48,
    "Trapèzes":        48,
    "Adducteurs":      48,
    "Biceps":          36,
    "Triceps":         36,
    "Mollets":         36,
    "Avant-bras":      24,
    "Abdominaux":      24,
    "Obliques":        24,
    "Cardio":          12,
    "Corps entier":    48
};

// Retourne la liste pondérée des muscles d'un exercice :
//   [{ muscle: "Pectoraux", ratio: 1.0 }, { muscle: "Triceps", ratio: 0.5 }, ...]
// Le principal est toujours en premier avec ratio 1.0.
function getWeightedMuscles(exercise) {
    if (!exercise) return [];
    const out = [];
    if (exercise.muscle) out.push({ muscle: exercise.muscle, ratio: 1.0 });
    if (Array.isArray(exercise.secondaryMuscles)) {
        exercise.secondaryMuscles.forEach(sm => {
            if (sm && sm.muscle && typeof sm.ratio === 'number' && sm.ratio > 0) {
                // Éviter de dupliquer le muscle principal
                if (sm.muscle !== exercise.muscle) out.push({ muscle: sm.muscle, ratio: sm.ratio });
            }
        });
    }
    return out;
}

// Temps de récup d'un muscle (heures), avec valeur par défaut prudente.
function getMuscleRecoveryHours(muscleName) {
    return MUSCLE_RECOVERY_HOURS[muscleName] || 48;
}

// Exposition globale
if (typeof window !== 'undefined') {
    window.MUSCLE_RECOVERY_HOURS = MUSCLE_RECOVERY_HOURS;
    window.getWeightedMuscles = getWeightedMuscles;
    window.getMuscleRecoveryHours = getMuscleRecoveryHours;
}

// 🔗 Exposé sur window : permet à disciplines.js d'AJOUTER les exercices des
// disciplines (Pilates, Yoga…) à la bibliothèque. Un `const` de script classique
// n'est pas accessible via window, d'où cette liaison explicite.
try { window.exerciseDatabase = exerciseDatabase; } catch (e) {}
